//! R036/05: Editor UTF-8 replace range on real source. Real guest filesystem/workstation operation.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
pub fn patch<const F:usize>(fs:&mut RamFs<F>,path:&[u8],rev:u64,start:usize,end:usize,insert:&[u8])->Result<u64,Error>{let(actual,n)=fs.metadata(path).map_err(|_|Error::Missing)?;if actual!=rev{return Err(Error::Stale);}let mut data=[0;CONTENT_MAX];fs.read(path,0,&mut data[..n]).map_err(|_|Error::Missing)?;let original=core::str::from_utf8(&data[..n]).map_err(|_|Error::Invalid)?;if start>end||end>n||!original.is_char_boundary(start)||!original.is_char_boundary(end)||core::str::from_utf8(insert).is_err(){return Err(Error::Invalid);}let size=n-(end-start)+insert.len();if size>CONTENT_MAX{return Err(Error::Full);}let mut updated=[0;CONTENT_MAX];updated[..start].copy_from_slice(&data[..start]);updated[start..start+insert.len()].copy_from_slice(insert);updated[start+insert.len()..size].copy_from_slice(&data[end..n]);fs.replace(path,&updated[..size]).map_err(|_|Error::Full)}
#[cfg(test)]mod tests{use super::*;#[test]fn real_functional_regression(){let mut fs=RamFs::<1>::new();fs.replace(b"/p/a","aβc".as_bytes()).unwrap();patch(&mut fs,b"/p/a",1,1,3,b"XYZ").unwrap();let mut b=[0;5];fs.read(b"/p/a",0,&mut b).unwrap();assert_eq!(&b,b"aXYZc");}}
